using System;using System.IO;using System.Linq;using System.Net;using System.Net.Http;using System.Net.Http.Headers;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;using System.IO.Compression;
namespace ExtremeLand {public static class SelfTests {
static void Check(bool v,string m){if(!v)throw new Exception(m);}static void Fails(Action a,string m){bool f=false;try{a();}catch{f=true;}Check(f,m);}
static PackFile Spec(string s,string n){return new PackFile{path="mods/"+n,url=new Uri(s).AbsoluteUri,size=new FileInfo(s).Length,sha256=Engine.Hash(s)};}
sealed class Ranges:HttpMessageHandler {public byte[] Data;public long From;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage q,CancellationToken t){From=q.Headers.Range==null?0:q.Headers.Range.Ranges.First().From.Value;var r=new HttpResponseMessage(From>0?HttpStatusCode.PartialContent:HttpStatusCode.OK);r.Content=new ByteArrayContent(Data.Skip((int)From).ToArray());if(From>0)r.Content.Headers.ContentRange=new ContentRangeHeaderValue(From,Data.Length-1,Data.Length);return Task.FromResult(r);}}
public static int Run(string root,string backend){Directory.CreateDirectory(root);var results=new Dictionary<string,object>();string input=Path.Combine(root,"input");Directory.CreateDirectory(input);string a=Path.Combine(input,"a.jar"),b=Path.Combine(input,"b.jar");File.WriteAllText(a,"one");File.WriteAllText(b,"two");using(var e=new Engine(Path.Combine(root,"client"),true)){
var p=new Pack{version="1",files=new List<PackFile>{Spec(a,"a.jar")}};e.Apply(p,4096,CancellationToken.None).GetAwaiter().GetResult();Check(Engine.Hash(Path.Combine(e.Game,"mods/a.jar"))==Engine.Hash(a),"Initial install");results["initialInstall"]=true;
string save=Path.Combine(e.Game,"saves/World/level.dat");Directory.CreateDirectory(Path.GetDirectoryName(save));File.WriteAllText(save,"keep");string extra=Path.Combine(e.Game,"mods/unmanaged.jar");File.WriteAllText(extra,"addon");var p2=new Pack{version="2",files=new List<PackFile>{Spec(b,"b.jar")}};e.Apply(p2,4096,CancellationToken.None).GetAwaiter().GetResult();Check(!File.Exists(Path.Combine(e.Game,"mods/a.jar"))&&File.ReadAllText(save)=="keep"&&File.ReadAllText(extra)=="addon","World/addon lost");Check(Directory.GetFiles(e.Safe("backups"),"a.jar",SearchOption.AllDirectories).Length==1,"Backup missing");results["updateKeepsWorldsAndBacksUpMods"]=true;
string ledger=File.ReadAllText(e.Safe("installed.json"));var bad=new Pack{version="bad",files=new List<PackFile>{Spec(a,"b.jar")}};bad.files[0].sha256=new string('0',64);Fails(()=>e.Apply(bad,4096,CancellationToken.None).GetAwaiter().GetResult(),"Corruption accepted");Check(File.ReadAllText(e.Safe("installed.json"))==ledger,"Corrupt update changed ledger");results["corruptDownloadRejected"]=true;
var p3=new Pack{version="3",files=new List<PackFile>{Spec(a,"b.jar")}};e.TestFaultAfter=1;Fails(()=>e.Apply(p3,4096,CancellationToken.None).GetAwaiter().GetResult(),"Fault injection");e.TestFaultAfter=-1;Check(Engine.Hash(Path.Combine(e.Game,"mods/b.jar"))==Engine.Hash(b)&&File.ReadAllText(e.Safe("installed.json"))==ledger,"Rollback failed");results["failedCommitRollsBack"]=true;
using(var l=File.Open(Path.Combine(e.Game,"mods/b.jar"),FileMode.Open,FileAccess.Read,FileShare.Read))Fails(()=>e.Apply(p3,4096,CancellationToken.None).GetAwaiter().GetResult(),"Active JAR changed");using(var l=File.Open(e.Safe("update.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None))Fails(()=>e.Apply(p3,4096,CancellationToken.None).GetAwaiter().GetResult(),"Concurrent update");results["activeFilesAndConcurrentUpdatesBlocked"]=true;
var evil=new Pack{version="evil",files=new List<PackFile>{Spec(a,"valid.jar")}};evil.files[0].path="mods/../../escape.jar";Fails(()=>e.Validate(evil),"Traversal accepted");evil.files[0].path="saves/level.dat";Fails(()=>e.Validate(evil),"World overwrite accepted");results["manifestRestrictedToMods"]=true;
string zip=Path.Combine(input,"evil.zip");using(var z=ZipFile.Open(zip,ZipArchiveMode.Create))using(var wr=new StreamWriter(z.CreateEntry("../escape.exe").Open()))wr.Write("no");Fails(()=>e.ExtractSafe(zip,e.Safe("zip")),"Zip escaped");results["zipSlipBlocked"]=true;
var cts=new CancellationTokenSource();cts.Cancel();Fails(()=>e.Apply(p3,4096,cts.Token).GetAwaiter().GetResult(),"Cancel ignored");Check(File.ReadAllText(e.Safe("installed.json"))==ledger,"Cancel altered state");results["cancelPreservesInstallation"]=true;
string world=Path.Combine(input,"MyWorld");Directory.CreateDirectory(world);File.WriteAllText(Path.Combine(world,"level.dat"),"original");File.WriteAllText(Path.Combine(world,"session.lock"),"lock");string imported=e.ImportWorld(world);Check(File.ReadAllText(Path.Combine(imported,"level.dat"))=="original"&&File.Exists(Path.Combine(world,"level.dat"))&&!File.Exists(Path.Combine(imported,"session.lock")),"World import");results["worldImportCopiesOriginal"]=true;
string profile=Path.Combine(input,"profile");Directory.CreateDirectory(Path.Combine(profile,"mods"));File.Copy(a,Path.Combine(profile,"mods/a.jar"));File.WriteAllText(Path.Combine(profile,"accounts.json"),"private");string output=Path.Combine(input,"publish");var built=Publisher.Prepare(profile,output,"example/extremeland","2.0.3");Check(built.files.Count==1&&!File.Exists(Path.Combine(output,"accounts.json")),"Publisher copied private data");results["publisherDoesNotCopyAccounts"]=true;
}
byte[] bytes=new byte[1048576];new Random(7).NextBytes(bytes);string data=Path.Combine(input,"range.bin");File.WriteAllBytes(data,bytes);string hash=Engine.Hash(data);var handler=new Ranges{Data=bytes};using(var e=new Engine(Path.Combine(root,"range"),true,handler)){Directory.CreateDirectory(e.Safe("cache"));File.WriteAllBytes(e.Safe("cache/"+hash+".part"),bytes.Take(65536).ToArray());string cached=e.Download("https://unit.invalid/range",hash,bytes.Length,"test",CancellationToken.None).GetAwaiter().GetResult();Check(handler.From==65536&&Engine.Hash(cached)==hash,"Resume failed");results["rangeResumeVerified"]=true;}
string shared=Path.Combine(root,"ConfiguredLauncher.exe");Publisher.Export(System.Reflection.Assembly.GetExecutingAssembly().Location,shared,new Config{channel=Engine.Channel("example/extremeland")});Check(Publisher.Embedded(shared).channel==Engine.Channel("example/extremeland"),"EXE channel missing");results["oneFileExportCarriesChannel"]=true;
if(backend!=null)using(var e=new Engine(Path.Combine(root,"backend"),true)){Check(Engine.Hash(backend)==Engine.PrismHash,"Backend checksum");Directory.CreateDirectory(e.Safe("cache"));File.Copy(backend,e.Safe("cache/"+Engine.PrismHash));e.EnsureBackend(CancellationToken.None).GetAwaiter().GetResult();Check(File.Exists(e.Backend),"Backend extraction");results["officialBackendVerifiedAndInstalled"]=true;}
results["passed"]=true;Json.Write(Path.Combine(root,"tests.json"),results);return 0;
}
}}
